"""No connectors wiring test vanishes while this phase rewrites its test files.

The release-wiring phase rewrites or deletes four test files that guard the
osprey-connectors release path (``BASE_FILES``). Before any of them changed, every
test id they collected at the base sha was recorded here (``BASE_IDS``, with its
sha256), whole files and parametrized cases included, so a test reached only
through a module constant or a helper cannot slip out of the record.

``connectors_wiring_test_map.json`` maps each of those old ids to the id that now
carries it: itself until a rewriting task renames, ports or deletes it. The map is
checked against the record, never the other way round, so a task that edits the
map cannot drop an old id from both sides. Each mapped id must be collected at the
compared head and must not be held back by a ``skip``, ``xfail`` or true ``skipif``
marker, and an old
``__mutation`` test must map to a mutation test.

The compared head is the working tree until the map records ``head_sha`` (the
phase-head sha); from then on it is that sha. The map proves no old test vanished;
whether a rewrite keeps every connectors assertion is the rewriting task's review
obligation. The test and the map are deleted by the first PR after the epic lands
on main.
"""

from __future__ import annotations

import hashlib
import json
import os
import platform
import subprocess
import sys
import tarfile
import tempfile
from collections.abc import Iterable, Mapping
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parents[2]
MAP_PATH = Path(__file__).with_name("connectors_wiring_test_map.json")

#: The collecting host's platform, as ``osprey.integrations.canopy.proven.venue()``
#: words it. ``tests/scripts/test_check.py`` puts that string into parametrize ids,
#: so an id is recorded and compared with it replaced by ``VENUE_TOKEN``: the same
#: test on another host is the same test.
HOST_VENUE = f"{platform.system()} {platform.machine()}"
VENUE_TOKEN = "<venue>"

#: The test files this phase rewrites or deletes.
BASE_FILES = (
    "tests/deployment/test_ci_workflow_wiring.py",
    "tests/scripts/test_connectors_compat_matrix.py",
    "tests/scripts/test_connectors_compat_lane.py",
    "tests/scripts/test_check.py",
)

# Runs in a fresh interpreter: a pytest collection inside this pytest run would
# share its plugins, rootdir and imported modules. Records every collected id and
# whether a marker holds it back: ``skip`` or ``xfail``, or a ``skipif`` whose
# condition is true, evaluated as pytest evaluates it at run time (module- and
# class-level ``pytestmark`` included). A ``pytest.skip()`` inside a test body is a
# run-time decision no collection can see.
_COLLECTOR = r"""
import json, sys
import pytest
from _pytest.skipping import evaluate_skip_marks, evaluate_xfail_marks

out, args = sys.argv[1], sys.argv[2:]

class Recorder:
    def __init__(self):
        self.items = {}

    def pytest_collection_finish(self, session):
        for item in session.items:
            try:
                held = evaluate_skip_marks(item) is not None or evaluate_xfail_marks(item) is not None
            except Exception:  # a condition that cannot be evaluated holds the test back
                held = True
            self.items[item.nodeid] = held

recorder = Recorder()
code = pytest.main(["--collect-only", "-q", "-p", "no:cacheprovider", *args], plugins=[recorder])
with open(out, "w", encoding="utf-8") as handle:
    json.dump({"exit": int(code), "items": recorder.items}, handle)
"""


def host_neutral(node_id: str, venue: str = HOST_VENUE) -> str:
    """``node_id`` with the collecting host's platform replaced by ``VENUE_TOKEN``."""
    return node_id.replace(venue, VENUE_TOKEN)


def digest(ids: Iterable[str]) -> str:
    """The sha256 of the sorted ids, one per line."""
    return hashlib.sha256("\n".join(sorted(ids)).encode()).hexdigest()


def collect(root: Path, files: Iterable[str]) -> dict[str, bool]:
    """Collect ``files`` (paths relative to ``root``) in a fresh pytest run.

    Returns every collected node id, host-neutral (``host_neutral``), mapped to
    whether it carries a skip marker.
    A file that does not exist is left out, so its ids read as not collected. Any
    other collection failure raises: a broken collection is never a pass.
    """
    present = sorted({f for f in files if (root / f).is_file()})
    if not present:
        return {}
    # The tree's own sources come first, so a materialized sha imports its own code.
    source_dirs = [root / "src", *sorted((root / "packages").glob("*/src"))]
    env = dict(os.environ)
    env.pop("PYTEST_ADDOPTS", None)
    env["PYTHONPATH"] = os.pathsep.join(
        [str(d) for d in source_dirs if d.is_dir()]
        + ([env["PYTHONPATH"]] if env.get("PYTHONPATH") else [])
    )
    with tempfile.TemporaryDirectory() as scratch:
        out = Path(scratch) / "collected.json"
        proc = subprocess.run(
            [sys.executable, "-c", _COLLECTOR, str(out), *present],
            cwd=root,
            env=env,
            capture_output=True,
            text=True,
            check=False,
        )
        if not out.is_file():
            raise RuntimeError(f"collection in {root} crashed:\n{proc.stdout}\n{proc.stderr}")
        result = json.loads(out.read_text(encoding="utf-8"))
    if result["exit"] != 0:
        raise RuntimeError(
            f"collection of {present} in {root} exited {result['exit']}:\n{proc.stdout[-4000:]}"
        )
    return {host_neutral(node): held for node, held in result["items"].items()}


def materialize(sha: str, dest: Path) -> Path:
    """Write the tree at ``sha`` into ``dest`` as a fresh repository of its own.

    No checkout of the shared repository: the tree is archived, then indexed in a
    throwaway repository, because collection reads ``git ls-files`` (``scripts/check.py``
    finds its owner modules that way).
    """
    archive = dest / "tree.tar"
    with archive.open("wb") as handle:
        subprocess.run(
            ["git", "-C", str(REPO_ROOT), "archive", "--format=tar", sha],
            stdout=handle,
            check=True,
        )
    root = dest / "tree"
    with tarfile.open(archive) as tar:
        tar.extractall(root, filter="data")
    archive.unlink()
    for args in (["init", "-q"], ["add", "-A", "-f"]):
        subprocess.run(["git", "-C", str(root), *args], check=True, capture_output=True)
    return root


def _function_name(node_id: str) -> str:
    return node_id.rsplit("::", 1)[-1].split("[", 1)[0]


def is_mutation(node_id: str) -> bool:
    return "__mutation" in _function_name(node_id)


def base_errors(ids: Iterable[str], expected_digest: str) -> list[str]:
    """Why the recorded base collection is not the one that was taken."""
    ids = list(ids)
    errors = []
    if len(set(ids)) != len(ids):
        errors.append("the base collection lists an id twice")
    if digest(ids) != expected_digest:
        errors.append(f"the base collection hashes to {digest(ids)}, recorded {expected_digest}")
    return errors


def map_errors(
    mapping: Mapping[str, str], base_ids: Iterable[str], collected: Mapping[str, bool]
) -> list[str]:
    """Every way ``mapping`` fails to carry each base id to a running test at the head."""
    base = set(base_ids)
    errors = [f"old id missing from the map: {old}" for old in sorted(base - mapping.keys())]
    errors += [f"map key is not a base id: {old}" for old in sorted(mapping.keys() - base)]
    for old in sorted(mapping.keys() & base):
        new = mapping[old]
        if not isinstance(new, str) or not new:
            errors.append(f"{old} maps to no test id: {new!r}")
            continue
        if new not in collected:
            errors.append(f"{old} maps to {new}, which is not collected")
        elif collected[new]:
            errors.append(f"{old} maps to {new}, which carries a skip/xfail marker")
        if is_mutation(old) and not is_mutation(new):
            errors.append(f"mutation {old} maps to non-mutation {new}")
    return errors


def head_files(mapping: Mapping[str, str]) -> set[str]:
    """The files the mapped ids live in."""
    return {new.split("::", 1)[0] for new in mapping.values() if isinstance(new, str) and new}


def load_map() -> dict:
    return json.loads(MAP_PATH.read_text(encoding="utf-8"))


# --------------------------------------------------------------------------- the guard


def test_the_recorded_base_collection_is_intact() -> None:
    assert base_errors(BASE_IDS, BASE_DIGEST) == []
    assert list(BASE_IDS) == sorted(BASE_IDS)
    assert {node.split("::", 1)[0] for node in BASE_IDS} == set(BASE_FILES)


def test_the_map_names_the_recorded_base() -> None:
    record = load_map()
    assert record["base_sha"] == BASE_SHA
    assert record["files"] == list(BASE_FILES)


def test_the_recorded_base_collection_is_the_collection_at_the_base_sha(tmp_path: Path) -> None:
    root = materialize(BASE_SHA, tmp_path)
    assert sorted(collect(root, BASE_FILES)) == list(BASE_IDS)


def test_every_base_test_is_carried_by_a_running_test_at_the_head(tmp_path: Path) -> None:
    record = load_map()
    mapping = record["map"]
    head_sha = record.get("head_sha")
    root = materialize(head_sha, tmp_path) if head_sha else REPO_ROOT
    collected = collect(root, head_files(mapping))
    errors = map_errors(mapping, BASE_IDS, collected)
    assert not errors, "\n".join(errors)


# --------------------------------------------------------------------------- self-tests

_SELF_BASE = (
    "tests/test_a.py::test_plain",
    "tests/test_a.py::test_case[one]",
    "tests/test_a.py::test_case[two]",
    "tests/test_a.py::test_plain__mutation_drops_a_line",
)


def _identity() -> dict[str, str]:
    return {old: old for old in _SELF_BASE}


def _running(ids: Iterable[str] = _SELF_BASE) -> dict[str, bool]:
    return dict.fromkeys(ids, False)


def test_self_the_identity_map_passes() -> None:
    assert map_errors(_identity(), _SELF_BASE, _running()) == []


def test_self_a_removed_entry_fails() -> None:
    mapping = _identity()
    del mapping["tests/test_a.py::test_plain"]
    assert map_errors(mapping, _SELF_BASE, _running()) == [
        "old id missing from the map: tests/test_a.py::test_plain"
    ]


def test_self_an_old_id_removed_from_the_keys_fails_even_when_its_target_remains() -> None:
    """Re-keying an entry under a new name drops the old id although its value survives."""
    mapping = _identity()
    mapping["tests/test_b.py::test_plain"] = mapping.pop("tests/test_a.py::test_plain")
    errors = map_errors(mapping, _SELF_BASE, _running())
    assert "old id missing from the map: tests/test_a.py::test_plain" in errors
    assert "map key is not a base id: tests/test_b.py::test_plain" in errors


def test_self_an_old_id_dropped_from_the_base_record_fails() -> None:
    """Dropping an id from the record itself (to hide it from the map check) breaks the hash."""
    shorter = _SELF_BASE[1:]
    assert base_errors(shorter, digest(_SELF_BASE))


def test_self_a_dropped_parametrize_case_fails() -> None:
    head = _running(node for node in _SELF_BASE if not node.endswith("[two]"))
    assert map_errors(_identity(), _SELF_BASE, head) == [
        "tests/test_a.py::test_case[two] maps to tests/test_a.py::test_case[two], "
        "which is not collected"
    ]


def test_self_a_mapped_id_that_is_not_collected_fails() -> None:
    mapping = _identity()
    mapping["tests/test_a.py::test_plain"] = "tests/test_new.py::test_plain"
    assert map_errors(mapping, _SELF_BASE, _running()) == [
        "tests/test_a.py::test_plain maps to tests/test_new.py::test_plain, which is not collected"
    ]


def test_self_a_mapped_id_marked_skip_fails() -> None:
    head = _running()
    head["tests/test_a.py::test_plain"] = True
    assert map_errors(_identity(), _SELF_BASE, head) == [
        "tests/test_a.py::test_plain maps to tests/test_a.py::test_plain, "
        "which carries a skip/xfail marker"
    ]


def test_self_a_mutation_mapped_to_a_plain_test_fails() -> None:
    mapping = _identity()
    mapping["tests/test_a.py::test_plain__mutation_drops_a_line"] = "tests/test_a.py::test_plain"
    assert map_errors(mapping, _SELF_BASE, _running()) == [
        "mutation tests/test_a.py::test_plain__mutation_drops_a_line maps to non-mutation "
        "tests/test_a.py::test_plain"
    ]


def test_self_a_mutation_mapped_to_a_mutation_passes() -> None:
    mapping = _identity()
    mapping["tests/test_a.py::test_plain__mutation_drops_a_line"] = (
        "tests/test_b.py::test_ported__mutation_drops_a_line"
    )
    head = _running([*_SELF_BASE, "tests/test_b.py::test_ported__mutation_drops_a_line"])
    assert map_errors(mapping, _SELF_BASE, head) == []


def test_self_collection_sees_parametrize_cases_and_skip_markers(tmp_path: Path) -> None:
    """The real collector, on a tiny project: cases are ids, and every skip form is seen."""
    (tmp_path / "pytest.ini").write_text("[pytest]\n", encoding="utf-8")
    (tmp_path / "test_tiny.py").write_text(
        "import pytest\n"
        "def test_runs(): pass\n"
        "@pytest.mark.parametrize('x', ['one', 'two'])\n"
        "def test_case(x): pass\n"
        "@pytest.mark.skip(reason='r')\n"
        "def test_skipped(): pass\n"
        "@pytest.mark.skipif(True, reason='r')\n"
        "def test_skipif_true(): pass\n"
        "@pytest.mark.skipif(False, reason='r')\n"
        "def test_skipif_false(): pass\n"
        "@pytest.mark.xfail\n"
        "def test_xfail(): pass\n"
        "class TestMarked:\n"
        "    pytestmark = pytest.mark.skip(reason='r')\n"
        "    def test_inside(self): pass\n",
        encoding="utf-8",
    )
    collected = collect(tmp_path, ["test_tiny.py", "test_missing.py"])
    assert collected == {
        "test_tiny.py::test_runs": False,
        "test_tiny.py::test_case[one]": False,
        "test_tiny.py::test_case[two]": False,
        "test_tiny.py::test_skipped": True,
        "test_tiny.py::test_skipif_true": True,
        "test_tiny.py::test_skipif_false": False,
        "test_tiny.py::test_xfail": True,
        "test_tiny.py::TestMarked::test_inside": True,
    }


def test_self_ids_from_another_host_compare_equal() -> None:
    darwin = "t.py::test_x[proven on <venue>]"
    linux = "t.py::test_x[proven on Linux x86_64]"
    assert host_neutral(darwin, "Darwin arm64") == host_neutral(linux, "Linux x86_64")
    assert host_neutral(darwin, "Darwin arm64") == "t.py::test_x[proven on <venue>]"


def test_self_a_broken_collection_raises(tmp_path: Path) -> None:
    (tmp_path / "pytest.ini").write_text("[pytest]\n", encoding="utf-8")
    (tmp_path / "test_broken.py").write_text("import not_a_module_anywhere\n", encoding="utf-8")
    with pytest.raises(RuntimeError, match="exited"):
        collect(tmp_path, ["test_broken.py"])


